('email') }}" required>@error('email')<p class="field-error">{{ $message }}</p>@enderror</div><div class="field full"><label>Phone</label><input name="phone" value="{{ old('phone') }}" placeholder="+44 7700 000000">@error('phone')<p class="field-error">{{ $message }}</p>@enderror</div><div class="field"><label>Password</label><input type="password" name="password" minlength="6" required><small>At least 6 characters.</small>@error('password')<p class="field-error">{{ $message }}</p>@enderror</div><div class="field"><label>Confirm password</label><input type="password" name="password_confirmation" required>@error('password_confirmation')<p class="field-error">{{ $message }}</p>@enderror</div></div><button class="button" type="submit">Create account</button></form></div><div class="auth-panel hidden" id="login-panel"><h2 class="modal-title">Welcome back</h2><p class="modal-sub">Sign in to continue with your selected assessment.</p><form method="post" action="{{ url('sign-in') }}">@csrf<input type="hidden" name="intended_package" class="selected-package" value="{{ old('intended_package') }}"><input type="hidden" name="purchase_flow" value="1"><div class="field"><label>Email or username</label><input name="user_name" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><p style="text-align:right"><a class="text-link" href="{{ url('forgot-password') }}">Forgot password?</a></p><button class="button" type="submit">Log in</button></form></div></div></div>
