@push('scripts')<script>(function(){var modal=document.getElementById('auth-modal'),selected='';function open(pkg){selected=pkg;document.querySelectorAll('.selected-package').forEach(function(el){el.value=pkg});modal.classList.add('open');modal.setAttribute('aria-hidden','false')}document.querySelectorAll('.choose-plan').forEach(function(btn){btn.addEventListener('click',function(){open(btn.dataset.package)})});document.querySelector('.close').addEventListener('click',function(){modal.classList.remove('open')});modal.addEventListener('click',function(e){if(e.target===modal)modal.classList.remove('open')});document.querySelectorAll('[data-panel]').forEach(function(btn){btn.addEventListener('click',function(){document.querySelectorAll('[data-panel]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.getElementById('register-panel').classList.toggle('hidden',btn.dataset.panel!=='register');document.getElementById('login-panel').classList.toggle('hidden',btn.dataset.panel!=='login')})});document.querySelectorAll('#auth-modal form').forEach(function(form){form.addEventListener('submit',function(){var button=form.querySelector('button[type="submit"]');if(!button||button.disabled){return}var label=button.textContent.trim();button.disabled=true;button.classList.add('is-loading');button.setAttribute('aria-busy','true');button.innerHTML='<span class="button-spinner" aria-hidden="true"></span><span>'+(label==='Create account'?'Creating account…':'Signing in…')+'</span>'})});})();</script>@endpush
